import{_ as o,o as d,c as e,a5 as a}from"./chunks/framework.BEZBAInb.js";const k=JSON.parse('{"title":"KonadoScript 编辑器","description":"","frontmatter":{"title":"KonadoScript 编辑器","order":5},"headers":[],"relativePath":"zh/latest/tutorial/core/ks-editor-highlighter.md","filePath":"zh/latest/tutorial/core/ks-editor-highlighter.md","lastUpdated":1788455378000}'),i={name:"zh/latest/tutorial/core/ks-editor-highlighter.md"};function c(r,t,s,l,n,h){return d(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="godot-内置-konadoscript-编辑器" tabindex="-1">Godot 内置 KonadoScript 编辑器 <a class="header-anchor" href="#godot-内置-konadoscript-编辑器" aria-label="Permalink to &quot;Godot 内置 KonadoScript 编辑器&quot;">​</a></h1><p>启用 Konado 插件后，在文件系统面板中双击 <code>.ks</code> 文件，会像打开 <code>.gd</code> 文件一样进入 Godot 的脚本工作区。KonadoScript 使用 Godot 原生代码编辑器和文档标签，不再占用底部 Dock。</p><h2 id="编辑能力" tabindex="-1">编辑能力 <a class="header-anchor" href="#编辑能力" aria-label="Permalink to &quot;编辑能力&quot;">​</a></h2><ul><li>使用 Godot 脚本文档标签同时编辑多个 <code>.ks</code>、<code>.gd</code> 和其他脚本</li><li>编辑 <code>.ks</code> 时，左上脚本列表会切换为组件/指令树；首次打开时组件区与分支区的高度默认为 2:1，标题栏右侧的滑动开关可展开或折叠全部分组，折叠后保留最外层分类，选择条目即可插入对应语句；左下成员大纲仍用于分支跳转</li><li>“在线文档”会根据编辑器语言打开 <code>2.4 LTS</code> 或 <code>latest</code> 文档；编辑 <code>.ks</code> 时会隐藏不支持 KonadoScript 的 Godot API 帮助搜索，切换到其他脚本语言后恢复 Godot 原有界面</li><li>当前剧本存在语言变体时，“在线文档”右侧会显示语言下拉列表，可在“默认”和已发现的本地化剧本之间直接切换</li><li>由 Godot 统一处理撤销重做、未保存状态、外部修改和关闭确认</li><li>直接使用脚本编辑器的查找替换、跳转行、缩放、书签和快捷键</li><li>在文件系统的“新建”菜单中直接创建带有有效初始内容的 KonadoScript</li><li>将 <code>branch</code> 声明显示在成员大纲中；分支、变量和信号均支持转到定义、查找引用及安全重命名</li><li>按住 Ctrl（macOS 为 Command）点击背景、演员、角色状态、动作、BGM、音效、语音、镜头配置或 <code>jump</code> 路径，可直接打开实际场景、资源或目标 KonadoScript；存在多个目标时会显示选择列表</li><li>悬停指令或资源标识符可查看签名、用途、解析路径和未解析状态，只有确实存在目标的内容才会显示可点击下划线</li><li>右键菜单提供文档或选区格式化、快速修复、转到定义、查找引用和安全重命名；跨文件资源重命名会先显示变更预览</li><li>根据条件块和全屏文本块自动缩进，并遵循 Godot 的缩进设置</li><li>保存时写回原始 <code>.ks</code>，并刷新由资源加载器编译的运行时 <code>KonadoShot</code></li></ul><h2 id="高亮与补全" tabindex="-1">高亮与补全 <a class="header-anchor" href="#高亮与补全" aria-label="Permalink to &quot;高亮与补全&quot;">​</a></h2><p><code>KonadoScriptSyntaxHighlighter</code> 基于 Godot 的 <code>EditorSyntaxHighlighter</code> 实现，并在插件启用时注册到脚本编辑器。高亮和代码补全共同读取 <code>KonadoScriptLanguageCatalog</code>，合法关键字以解析器中的 <code>KonadoScriptToken.KEYWORDS</code> 为准。自动化测试会检查二者是否一致。</p><p>补全除了指令、子命令和可插入语句模板，还会按当前指令提供 2.8 命名参数，并避免重复建议已经填写的参数。项目资源中的 KonadoScript 路径、演员、角色状态、动作、背景、音频和镜头也会纳入补全；角色状态与自定义动作会按当前演员过滤，对话语音补全能正确处理含空格的引号文本。当前文档中的分支、变量和信号会即时纳入建议。命名参数会获得独立高亮，正式编译器仍负责最终的类型、范围、冲突与重复 ID 校验。高亮规则只在首次使用时编译，并且每行只记录颜色变化的位置。</p><p>默认高亮资源位于：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>res://addons/konado/editor/script_editor/konado_script_highlighter.tres</span></span></code></pre></div><p>其他 <code>CodeEdit</code> 也可以直接使用高亮器：</p><div class="language-gdscript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gdscript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set_syntax_highlighter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">KonadoScriptSyntaxHighlighter</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">())</span></span></code></pre></div><h2 id="实时诊断" tabindex="-1">实时诊断 <a class="header-anchor" href="#实时诊断" aria-label="Permalink to &quot;实时诊断&quot;">​</a></h2><p>停止输入片刻后，Godot 会通过 KonadoScript 语言桥接层执行词法、语法和语义分析，但不会生成运行时 <code>KonadoShot</code>。错误和警告会显示在对应代码行及脚本编辑器内置的问题面板中，并根据 Godot 编辑器语言使用中文或英文。分析器会一次报告多行独立错误，并检查多余参数、错误的数值或布尔值、无效跳转路径、未知资源 ID、缺失目标文件、演员生命周期和本地化剧本结构；错误输入不会让实时检查停滞。</p><p>悬停错误范围会显示宽高随内容自适应的诊断卡片。每条诊断最多提供三个按可能性排序的“尝试”方案；需要用户判断的候选项不会被“应用全部安全快速修复”自动选择。无法自动修复的问题会提供资源配置或文档入口。修复会作为一次可撤销操作应用，并保留光标、选择区、多光标、折叠和滚动位置。</p><p>点击问题即可跳转到相关位置。即使现有文件含有语法错误，也仍可在脚本编辑器中打开和修复；保存后资源加载器会重新执行正式编译，因此实时诊断不能替代最终加载结果。</p><h2 id="运行时调试" tabindex="-1">运行时调试 <a class="header-anchor" href="#运行时调试" aria-label="Permalink to &quot;运行时调试&quot;">​</a></h2><p>可使用 Godot 的断点控制 KonadoScript 执行。运行到断点时，调试器会打开对应 <code>.ks</code> 行，并显示当前镜头、节点、持久变量和临时变量；调试页提供继续、单步和“在下一行暂停”操作。发布导出不启用编辑器调试会话。</p><h2 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>Windows / Linux</th><th>macOS</th></tr></thead><tbody><tr><td>保存</td><td><code>Ctrl+S</code></td><td><code>Command+S</code></td></tr><tr><td>关闭当前标签</td><td><code>Ctrl+W</code></td><td><code>Command+W</code></td></tr><tr><td>查找</td><td><code>Ctrl+F</code></td><td><code>Command+F</code></td></tr><tr><td>查找与替换</td><td><code>Ctrl+H</code></td><td><code>Command+Option+F</code></td></tr><tr><td>跳转到行</td><td><code>Ctrl+L</code></td><td><code>Command+L</code></td></tr></tbody></table>',19)])])}const g=o(i,[["render",c]]);export{k as __pageData,g as default};
